package embedding

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"path/filepath"
	"strings"
)

// ReleaseBaseURL is the GitHub release that hosts first-run model assets
// (same release as DefaultModelDownloadURL).
const ReleaseBaseURL = "https://github.com/RapidAI/MaClaw/releases/download/Model_Release"

// release_assets.json is generated by
// /workspace/maclaw_reranker/scripts/gen_release_manifest.py (also writes the
// upload manifest). Filenames are stable; size + sha256 pin the bytes.
//
//go:embed release_assets.json
var releaseAssetsJSON []byte

// ReleaseAsset is one first-run downloadable file.
type ReleaseAsset struct {
	Filename string `json:"filename"`
	Kind     string `json:"kind"`   // model | intent_head | tool_head
	Subdir   string `json:"subdir"` // install dir under the models dir ("" = models dir)
	Size     int64  `json:"size"`
	SHA256   string `json:"sha256"`
}

// ReleaseAssets returns the embedded asset table.
func ReleaseAssets() []ReleaseAsset {
	var doc struct {
		Assets []ReleaseAsset `json:"assets"`
	}
	if err := json.Unmarshal(releaseAssetsJSON, &doc); err != nil {
		panic("embedding: bad release_assets.json: " + err.Error())
	}
	return doc.Assets
}

// Spec converts an asset to a ModelSpec with the GitHub release URL.
func (a ReleaseAsset) Spec() ModelSpec {
	return ModelSpec{Filename: a.Filename, URLs: []string{ReleaseBaseURL + "/" + a.Filename}, Size: a.Size, SHA256: a.SHA256}
}

// IsReleaseAssetFilename reports whether name is one of the pinned assets
// (the hub uses it to allow .json head files on /api/v1/models/).
func IsReleaseAssetFilename(name string) bool {
	for _, a := range ReleaseAssets() {
		if a.Filename == name {
			return true
		}
	}
	return false
}

func mustReleaseAsset(name string) ModelSpec {
	for _, a := range ReleaseAssets() {
		if a.Filename == name {
			return a.Spec()
		}
	}
	panic(fmt.Sprintf("embedding: release asset %s missing from release_assets.json", name))
}

// WithHubFallback appends the hub mirror URL (<hub>/api/v1/models/<file>,
// the endpoint every other guiapp model download falls back to) after the
// GitHub release URL.
func (s ModelSpec) WithHubFallback(hubURL string) ModelSpec {
	hubURL = strings.TrimRight(strings.TrimSpace(hubURL), "/")
	if hubURL == "" {
		return s
	}
	s.URLs = append(append([]string(nil), s.URLs...), hubURL+"/api/v1/models/"+s.Filename)
	return s
}

// NewReleaseAssetFetcher builds a fetcher for asset under modelsDir/<subdir>,
// GitHub release first, then the hub mirror. Head assets keep any existing
// local file (local / recalibrated heads win over the release copy).
func NewReleaseAssetFetcher(modelsDir string, a ReleaseAsset, hubURL string) *ModelFetcher {
	dir := modelsDir
	if a.Subdir != "" {
		dir = filepath.Join(modelsDir, a.Subdir)
	}
	f := NewModelFetcher(dir, a.Spec().WithHubFallback(hubURL))
	f.KeepExisting = a.Kind != "model"
	return f
}
